import{_ as t,o as r,c as o,a5 as i}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"预渲染","description":"由于SPA项目普通的爬虫无法爬取项目的静态文本的内容，通过预渲染插件prerender spa plugin( [https://github.com/chrisvfritz/prerender spa plugin)解决SPA项目的SEO问题解决SPA项目的SEO问题) pre。","frontmatter":{"title":"预渲染","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","工程化、质量与性能"],"description":"由于SPA项目普通的爬虫无法爬取项目的静态文本的内容，通过预渲染插件prerender spa plugin( [https://github.com/chrisvfritz/prerender spa plugin)解决SPA项目的SEO问题解决SPA项目的SEO问题) pre。","sidebarWeight":62,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/性能优化/预渲染.md"},"headers":[],"relativePath":"posts/Vue系统教程/06-工程化、质量与性能/预渲染.md","filePath":"posts/Vue系统教程/06-工程化、质量与性能/预渲染.md"}'),l={name:"posts/Vue系统教程/06-工程化、质量与性能/预渲染.md"};function n(s,e,a,u,p,d){return r(),o("div",null,[...e[0]||(e[0]=[i('<div><h1 id="预渲染" tabindex="-1">预渲染 <a class="header-anchor" href="#预渲染" aria-label="Permalink to &quot;预渲染&quot;">​</a></h1><blockquote><p>本节目标：理解“预渲染”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><blockquote><p>说明：原 OneNote 中有图片引用，但图片未包含在导出目录中；本页保留了可用的文字与代码内容。</p></blockquote><ul><li>由于SPA项目普通的爬虫无法爬取项目的静态文本的内容，通过预渲染插件[prerender-spa-plugin( <a href="https://github.com/chrisvfritz/prerender-spa-plugin)%E8%A7%A3%E5%86%B3SPA%E9%A1%B9%E7%9B%AE%E7%9A%84SEO%E9%97%AE%E9%A2%98" target="_blank" rel="noreferrer">https://github.com/chrisvfritz/prerender-spa-plugin)解决SPA项目的SEO问题</a></li><li>prerender-spa-plugin 利用了 Puppeteer 的爬取页面的功能。</li><li>Puppeteer 是一个 Chrome官方出品的 headless Chrome node 库。它提供了一系列的 API, 可以在无 UI 的情况下调用 Chrome 的功能, 适用于爬虫、自动化处理等各种场景</li><li>原理是在 Webpack 构建阶段的最后，在本地启动一个 Puppeteer 的服务，访问配置了预渲染的路由，然后将 Puppeteer 中渲染的页面输出到 HTML 文件中，并建立路由对应的目录</li></ul><p><strong>6.1 src\\index.js</strong> src\\index.js import React from &#39;react&#39;;import ReactDOM from &#39;react-dom&#39;;import {BrowserRouter as Router,Route,Link} from &#39;react-router-dom&#39;;let Home = props=&gt;&lt;div&gt;Home&lt;/div&gt;let User = props=&gt;&lt;div&gt;User&lt;/div&gt;let Profile = props=&gt;&lt;div&gt;Profile&lt;/div&gt;ReactDOM.render( &lt;Router&gt; &lt;&gt; &lt;Link to=&quot;/&quot;&gt;home&lt;/Link&gt; &lt;Link to=&quot;/user&quot;&gt;user&lt;/Link&gt; &lt;Link to=&quot;/profile&quot;&gt;profile&lt;/Link&gt; &lt;Route path=&quot;/&quot; exact={true} component={Home} /&gt; &lt;Route path=&quot;/user&quot; component={User} /&gt; &lt;Route path=&quot;/profile&quot; component={Profile}/&gt; &lt;/&gt; &lt;/Router&gt;,document.getElementById(&#39;root&#39;)); <strong>6.2 src\\index.html</strong> src\\index.html &lt;!DOCTYPE html&gt;&lt;htmllang=&quot;en&quot;&gt;&lt;head&gt;&lt;metacharset=&quot;UTF-8&quot;&gt;&lt;metaname=&quot;viewport&quot;content=&quot;width=device-width, initial-scale=1.0&quot;&gt;&lt;metahttp-equiv=&quot;X-UA-Compatible&quot;content=&quot;ie=edge&quot;&gt;&lt;title&gt;Document&lt;/title&gt;&lt;/head&gt;&lt;body&gt;&lt;divid=&quot;root&quot;&gt;&lt;/div&gt;&lt;/body&gt;&lt;/html&gt; <strong>6.3 webpack.config.js</strong> webpack.config.js constpath = require(&quot;path&quot;);constHtmlWebpackPlugin = require(&quot;html-webpack-plugin&quot;);constPrerenderSPAPlugin = require(&quot;./prerender-spa-plugin&quot;); module.exports = { mode: &quot;development&quot;, context: process.cwd(), entry: &quot;./src/index.js&quot;, output: { path: path.resolve(__dirname, &quot;dist&quot;), filename: &quot;bundle.js&quot;}, module: { rules: [ { test: /.jsx?$/, use: { loader: &quot;babel-loader&quot;, options: { presets: [&quot;@babel/preset-env&quot;, &quot;@babel/preset-react&quot;], plugins: [ [&quot;@babel/plugin-proposal-decorators&quot;, { legacy: true}], [&quot;@babel/plugin-proposal-class-properties&quot;, { loose: true}] ] } }, include: path.join(__dirname, &quot;src&quot;), exclude: /node_modules/} ] }, plugins: [ newHtmlWebpackPlugin({ template: &quot;./src/index.html&quot;, //指定模板文件filename: &quot;index.html&quot;//产出后的文件名}), newPrerenderSPAPlugin({ staticDir: path.join(__dirname, &quot;dist&quot;), routes: [&quot;/&quot;,&quot;/user&quot;,&quot;/profile&quot;] }) ]}; <strong>6.4 prerender-spa-plugin.js</strong> prerender-spa-plugin.js constpath = require(&quot;path&quot;);constPrerenderer = require(&quot;@prerenderer/prerenderer&quot;);constPuppeteerRenderer = require(&quot;@prerenderer/renderer-puppeteer&quot;);classPrerenderSPAPlugin{ constructor(options) { this._options = options; this._options.renderer = newPuppeteerRenderer({ headless: true}); } apply(compiler) { let_this = this; constcompilerFS = compiler.outputFileSystem; constafterEmit = (compilation, done) =&gt;{ constPrerendererInstance = newPrerenderer(_this._options); PrerendererInstance.initialize() .then(()=&gt;{ returnPrerendererInstance.renderRoutes(_this._options.routes || []); }) .then(renderedRoutes=&gt;{ letpromises = renderedRoutes.map(rendered=&gt;{ returnnewPromise(function(resolve) { rendered.outputPath = path.join( _this._options.staticDir, rendered.route, &quot;index.html&quot;); letdir = path.dirname(rendered.outputPath); compilerFS.mkdirp(dir, (err, made) =&gt; { compilerFS.writeFile( rendered.outputPath, rendered.html, err =&gt; { resolve(); } ); }); }); }); returnPromise.all(promises); }) .then(()=&gt;{ PrerendererInstance.destroy(); done(); }); }; compiler.hooks.afterEmit.tapAsync(&quot;PrerenderSPAPlugin&quot;, afterEmit); }}module.exports = PrerenderSPAPlugin; 不适合不同的用户看都会不同的页面，这种类型的页面不适用预渲染 对于一些经常发生变化的页面，如体育比赛等，会导致编译后的数据不是实时更新的 <strong>7. 图片懒加载</strong></p><ul><li><a href="https://github.com/twobin/react-lazyload" target="_blank" rel="noreferrer">react-lazyload</a></li><li><a href="http://img.zhufengpeixun.cn/lazyimages.zip" target="_blank" rel="noreferrer">lazyimages.zip</a></li></ul><p><strong>7.1 webpack.config.js</strong> webpack.config.js constpath = require(&#39;path&#39;);constHtmlWebpackPlugin=require(&#39;html-webpack-plugin&#39;);module.exports = { mode:&#39;development&#39;, context: process.cwd(), entry: &quot;./src/index.js&quot;, output: { path: path.resolve(__dirname, &quot;dist&quot;), filename: &quot;bundle.js&quot;}, module: { rules: [ { test: /.jsx?$/, use: { loader: &quot;babel-loader&quot;, options: { presets: [&quot;@babel/preset-env&quot;,&quot;@babel/preset-react&quot;], plugins: [ [&quot;@babel/plugin-proposal-decorators&quot;, { legacy: true}], [&quot;@babel/plugin-proposal-class-properties&quot;, { loose: true}] ] } }, include: path.join(__dirname, &quot;src&quot;), exclude: /node_modules/}, { test:/.(jpg|png|gif)$/, use:{loader:&#39;url-loader&#39;,options:{limit:0}} }, { test:/.css$/, use:[&quot;style-loader&quot;,&#39;css-loader&#39;] } ] }, plugins: [ newHtmlWebpackPlugin({ template:&#39;./src/index.html&#39;,//指定模板文件filename:&#39;index.html&#39;,//产出后的文件名}) ]}; <strong>7.2 index.js</strong> src\\index.js importReact from&quot;react&quot;;importReactDOM from&quot;react-dom&quot;;import&#39;./index.css&#39;;importLazyLoad from&quot;./react-lazyload&quot;;constApp = (props) =&gt;{ return( &lt;ulclassName=&quot;list&quot;style={{overflow:&#39;auto&#39;}}&gt;{ props.images.map((image,index)=&gt;( &lt;LazyLoadkey={index}height={200}&gt;&lt;li&gt;&lt;imgsrc={image}/&gt;&lt;/li&gt;&lt;/LazyLoad&gt;)) } &lt;/ul&gt;);};letimages = [ require(&#39;./images/1.jpg&#39;), require(&#39;./images/2.jpg&#39;), require(&#39;./images/3.jpg&#39;), require(&#39;./images/4.jpg&#39;), require(&#39;./images/5.jpg&#39;), require(&#39;./images/6.jpg&#39;), require(&#39;./images/7.jpg&#39;), require(&#39;./images/8.jpg&#39;),] ReactDOM.render(&lt;Appimages={images}/&gt;, document.getElementById(&quot;root&quot;)); <strong>7.3 index.css</strong> src\\index.css *{ margin: 0; padding: 0;}ul,li{ list-style: none;}liimg{ width:100%; height:100%;} <strong>7.4 react-lazyload.js</strong></p><ul><li><a href="https://developer.mozilla.org/zh-CN/docs/Web/API/Element/getBoundingClientRect" target="_blank" rel="noreferrer">getBoundingClientRect</a>返回值是一个 DOMRect 对象，这个对象是由该元素的 getClientRects() 方法返回的一组矩形的集合, 即：是与该元素相关的CSS 边框集合</li><li>DOMRect 对象包含了一组用于描述边框的只读属性——left、top、right和bottom，单位为像素。除了 width 和 height 外的属性都是相对于视口的左上角位置而言的</li></ul><p>src\\react-lazyload.js importReact from&quot;react&quot;;importReactDOM from&quot;react-dom&quot;;letlisteners = [];letlazyLoadHandler = ()=&gt;{ for(vari = 0; i &lt; listeners.length; ++i) { varlistener = listeners[i]; checkVisible(listener); }};letcheckVisible = component=&gt;{ letnode = ReactDOM.findDOMNode(component); let{ top } = node.getBoundingClientRect(); letvisible = top &lt;= (window.innerHeight || document.documentElement.clientHeight); if(visible) { listeners = listeners.filter(item=&gt;item != component); component.setState({visible}); }};classLazyLoadextendsReact.Component{ state = {visible:false} constructor(props) { super(props); this.divRef = React.createRef(); } componentDidMount() { if(listeners.length == 0) { window.addEventListener(&quot;scroll&quot;, lazyLoadHandler); } listeners.push(this); checkVisible(this); } render() { returnthis.state.visible ? ( this.props.children ) : ( &lt;divstyle={{height:this.props.height}} className=&quot;lazyload-placeholder&quot;ref={this.divRef}/&gt;); }}exportdefaultLazyLoad; <strong>8. 长列表优化</strong></p><ul><li>用数组保存所有列表元素的位置，只渲染可视区内的列表元素，当可视区滚动时，根据滚动的offset大小以及所有列表元素的位置，计算在可视区应该渲染哪些元素</li><li><a href="https://www.npmjs.com/package/react-window" target="_blank" rel="noreferrer">react-window</a></li><li><a href="https://react-window.now.sh/#/examples/list/fixed-size" target="_blank" rel="noreferrer">fixed-size</a></li><li><a href="https://www.npmjs.com/package/react-virtualized" target="_blank" rel="noreferrer">react-virtualized</a></li></ul><p><strong>8.1 index.js</strong> index.js importReact, { Component, lazy, Suspense } from&quot;react&quot;;importReactDOM from&quot;react-dom&quot;;import{ FixedSizeList asList } from&#39;./react-window&#39;;import&#39;./index.css&#39;constRow = ({ index, style }) =&gt;{ return&lt;divkey={index}style={{...style,backgroundColor:getRandomColor(),lineHeight:&#39;30px&#39;,textAlign:&#39;center&#39;}}&gt;Row {index+1}&lt;/div&gt;}; constContainer = ()=&gt;( &lt;Listheight={150}itemCount={100}itemSize={30}width={&#39;100%&#39;} &gt;{Row} &lt;/List&gt;);ReactDOM.render(&lt;Container/&gt;, document.querySelector(&quot;#root&quot;));functiongetRandomColor( ) { varrand = Math.floor(Math.random( ) * 0xFFFFFF).toString(16).toUpperCase(); if(rand.length == 6){ return&#39;#&#39;+rand; }else{ returngetRandomColor(); }} <strong>8.2 index.css</strong> index.css *{ margin: 0; padding: 0;}ul,li{ list-style: none;} <strong>8.3 react-window.js</strong> react-window.js importReact, { Component} from&quot;react&quot;;exportclassFixedSizeListextendsReact.Component{ state = {start:0} constructor(){ super(); this.containerRef = React.createRef(); } componentDidMount(){ this.containerRef.current.addEventListener(&#39;scroll&#39;,()=&gt;{ letscrollTop = this.containerRef.current.scrollTop; letstart = Math.floor(scrollTop/this.props.itemSize);<a href="//xn--this-uk7gy4y1x6bhclbz9a.setState" target="_blank" rel="noreferrer">//起始的索引this.setState</a>({start}); }); } render(){ let{width,height,itemCount,itemSize} = this.props; letchildren = []; letsize = Math.floor(height/itemSize)+1;//每页的条数letitemStyle = {height:itemSize,width:&#39;100%&#39;,position:&#39;absolute&#39;,left:0,top:0}; for(letindex=this.state.start;index&lt;this.state.start+size;index++){ letstyle = {...itemStyle,top:(index)<em>itemSize}; children.push(this.props.children({index,style})); } letcontainerStyle = {height,width:width||&#39;100%&#39;,position:&#39;relative&#39;,overflow:&#39;auto&#39;}; return( &lt;divstyle={containerStyle}ref={this.containerRef}&gt;&lt;divstyle={{width:&#39;100%&#39;,height:itemSize</em>itemCount}}&gt;{children} &lt;/div&gt;&lt;/div&gt;) }} <strong>9. key的优化</strong><strong>9.1 diff策略</strong></p><ul><li>DOM节点跨节点层级移动可以忽略</li><li>相同类型的组件生成相似的结构，不同类型的组件生成不同的结构</li><li>对于同一层次的子节点可以通过唯一的key进行区分</li></ul><p><strong>9.2 tree diff</strong></p><ul><li>对树进行分层比较，两棵树只会对同一层次节点进行比较</li><li>当出现跨层级移动时，并不会出现移动操作，而是直接删除重建</li></ul><p><strong>9.3 组件diff</strong></p><ul><li>如果是同一个类型的组件，会向下继续比较子节点</li><li>如果类型不同，则替换组件下的所有子节点</li></ul><p><strong>9.4 element diff</strong> 当节点处于同一层级时，React diff 提供了三种节点操作,分别为：INSERT(插入)、MOVE(移动)和 REMOVE(删除)</p><ul><li>INSERT: 新的 component 类型不在老集合里， 即是全新的节点，需要对新节点执行插入操作</li><li>MOVE: 在老集合有新 component 类型，就需要做移动操作，可以复用以前的 DOM 节点</li><li>REMOVE: 老 component 不在新集合里的，也需要执行删除操作</li></ul><p><strong>10. React 性能分析器</strong></p><ul><li><a href="http://react.html.cn/blog/2018/09/10/introducing-the-react-profiler.html" target="_blank" rel="noreferrer">introducing-the-react-profiler</a></li><li>React 16.5 增加了对新的开发者工具 DevTools 性能分析插件的支持</li><li>此插件使用 React 实验性的 Profiler API 来收集有关每个组件渲染的用时信息，以便识别 React 应用程序中的性能瓶颈</li></ul><p><strong>10.1 分析解析</strong></p><ul><li>分析一个应用程序的性能（Profiling an application）</li><li>查看性能数据(render(渲染)阶段和commit(提交)阶段)</li><li>过滤 commits（Filtering commits）</li><li>火焰图表（Flame chart）</li><li>排序图表（Ranked chart）</li><li>组件图表（Component chart）</li><li>交互（Interactions）</li></ul><p><strong>10.2 react-flame-graph</strong></p><ul><li><a href="https://github.com/bvaughn/react-flame-graph" target="_blank" rel="noreferrer">react-flame-graph</a>是用来可视化性能数据的React组件 &gt; 来自 &lt;<a href="http://www.zhufengpeixun.com/strong/html/76.react_optimize.html" target="_blank" rel="noreferrer">http://www.zhufengpeixun.com/strong/html/76.react_optimize.html</a>&gt;</li></ul></div>',1)])])}const m=t(l,[["render",n]]);export{g as __pageData,m as default};
